class Solution {
public:
    int sumDivisibleByK(vector<int>& nums, int k) {
        unordered_map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        int ans = 0;
        for (auto& [v, f] : cnt)
            if (f % k == 0) ans += v * f;
        return ans;
    }
};

