class Solution {
    public int sumDivisibleByK(int[] nums, int k) {
        Map<Integer,Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        int ans = 0;
        for (var e : cnt.entrySet())
            if (e.getValue() % k == 0) ans += e.getKey() * e.getValue();
        return ans;
    }
}

